INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L1 — OCBOA historical terminology
(2, 'Special Purpose Frameworks', 'What is the former professional term for a special purpose framework?', '["Simplified reporting standard", "Other comprehensive basis of accounting", "Nonauthoritative reporting framework", "Alternative measurement basis"]'::jsonb, 1, 'Under AU-C Section 800, a special purpose framework (SPF) was historically called an other comprehensive basis of accounting (OCBOA). The AICPA replaced the OCBOA terminology with SPF in the clarified auditing standards. ''Simplified reporting standard'' and the other options are fabricated terms not recognized in professional literature.', 'easy', 1),

-- Q2: medium / L3 — Tax basis bad debts vs GAAP (direct write-off vs CECL)
(2, 'Special Purpose Frameworks', 'Westfield Services prepares tax-basis financial statements and has $120,000 of receivables considered doubtful. Under GAAP, the company would record an allowance using the current expected credit loss (CECL) model. The controller asks how to report the doubtful receivables on the tax-basis statements. Under the tax basis, how should these receivables be handled?', '["Record an allowance for doubtful accounts using the CECL model as required under ASC 326", "Estimate doubtful accounts using a percentage-of-sales method consistent with IRS regulations", "Write off specific receivables only when they become wholly or partially worthless under IRC Section 166", "Reduce receivables to net realizable value using a lower-of-cost-or-NRV approach"]'::jsonb, 2, 'Under IRC Section 166, the tax basis uses the direct write-off method — bad debts are deducted only when a specific receivable becomes worthless or partially worthless. The GAAP allowance method under ASC 326 (CECL) is not used. This is a fundamental tax-GAAP difference because the tax basis does not permit estimation of future losses; each bad debt must be individually identified and documented.', 'medium', 3),

-- Q3: medium / L2 — General-use vs special-use regulatory classification
(2, 'Special Purpose Frameworks', 'Meridian Savings Bank prepares regulatory basis financial statements required by the FFIEC for filing with federal banking agencies. The statements will also be distributed to the bank''s shareholders and posted on its website. The engagement partner is determining whether these are general-use or special-use statements. Which factor most directly determines the classification?', '["Whether the regulatory basis is substantially equivalent to GAAP", "Whether the statements are audited or compiled", "Whether the bank is publicly traded or privately held", "Whether the regulatory agency approves distribution to third parties"]'::jsonb, 0, 'Under AU-C Section 800, regulatory basis financial statements are general-use when the regulatory basis is substantially equivalent to GAAP, allowing broad distribution. When the basis differs significantly from GAAP, the statements are special-use and the auditor''s report must restrict distribution. The entity''s public/private status and the audit vs. compilation distinction do not determine the classification.', 'medium', 2),

-- Q4: easy / L1 — Five recognized SPF types
(2, 'Special Purpose Frameworks', 'How many types of special purpose frameworks are recognized under AU-C Section 800?', '["Three", "Four", "Six", "Five"]'::jsonb, 3, 'AU-C Section 800 recognizes five types of special purpose frameworks: cash basis, modified cash basis, tax basis, regulatory basis, and contractual basis. Candidates sometimes confuse the count by omitting the modified cash basis as a separate category or by combining regulatory and contractual into one. All five are distinct frameworks with different recognition and measurement rules.', 'easy', 1),

-- Q5: hard / L4 — Contractual vs regulatory overlap analysis
(2, 'Special Purpose Frameworks', 'Crestline Power Cooperative prepares financial statements under measurement and recognition rules prescribed by the state public utility commission. The cooperative''s primary lender also requires annual financial statements under the lending agreement, which specifies the same regulatory measurement rules plus additional reporting of off-balance-sheet commitments. The CFO proposes issuing one set of financial statements to satisfy both users. Evaluate which framework classification and reporting restrictions apply.', '["The statements qualify as regulatory basis for both users because the state commission''s rules form the underlying basis of measurement", "The statements cannot serve both purposes because the contractual basis adds requirements beyond the regulatory framework, creating a hybrid that must be classified and reported separately for each user", "The statements qualify as contractual basis for both users because the loan agreement incorporates and expands upon the regulatory provisions", "The statements qualify as both frameworks simultaneously and may be distributed to both parties with a single auditor''s report referencing both bases"]'::jsonb, 1, 'Under AU-C Section 800, contractual basis and regulatory basis are distinct frameworks. When a contract incorporates regulatory rules plus additional requirements, the combined financial statements create different obligations for different users. The regulatory user requires statements under the commission''s rules, while the lender requires contractual basis statements with additional disclosures. A single set cannot simultaneously satisfy both frameworks when the contractual terms add measurement requirements beyond the regulatory basis.', 'hard', 4),

-- Q6: medium / L2 — AU-C 800 emphasis-of-matter paragraph
(2, 'Special Purpose Frameworks', 'Hayward & Associates completes an audit of financial statements prepared on the income tax basis for Stratton Automotive Group. The auditor concludes the statements are fairly presented in accordance with the tax basis. Under AU-C Section 800, the auditor''s report on SPF financial statements must include which specific paragraph?', '["A qualified opinion paragraph stating the departure from GAAP", "An other-matter paragraph restricting distribution to the IRS only", "An emphasis-of-matter paragraph describing the SPF and referring to the related note", "A scope limitation paragraph explaining why GAAP was not applied"]'::jsonb, 2, 'AU-C Section 800.14 requires an emphasis-of-matter paragraph in the auditor''s report on SPF financial statements. This paragraph describes the special purpose framework used and refers to the note in the financial statements explaining the basis. There is no qualified opinion solely because the entity uses an SPF, and tax-basis statements are not restricted only to the IRS — they may be used by various parties.', 'medium', 2),

-- Q7: easy / L1 — Cash basis no depreciation
(2, 'Special Purpose Frameworks', 'Under the pure cash basis of accounting, how are long-lived assets reported?', '["Expensed in full when purchased because only cash disbursements are recorded", "Capitalized and depreciated over their useful lives", "Recorded at fair value with annual impairment testing", "Excluded from the financial statements entirely"]'::jsonb, 0, 'Under the pure cash basis, only cash receipts and disbursements are recorded. When a long-lived asset is purchased, the entire cash outflow is recorded as an expense in the period paid. No capitalization or depreciation occurs because those are accrual concepts. ''Excluded from the financial statements entirely'' is incorrect — the cash payment itself is recorded as an expense.', 'easy', 1),

-- Q8: easy / L1 — Substantial support definition
(2, 'Special Purpose Frameworks', 'What does "substantial support" mean in the context of the modified cash basis of accounting?', '["The financial statements must be supported by a formal audit opinion", "The entity must demonstrate revenue sufficient to support continued operations", "The modifications must be approved by a regulatory agency before implementation", "The accrual modifications must relate to transactions commonly adjusted under accepted practice"]'::jsonb, 3, 'Under professional standards, modifications to the cash basis must have ''substantial support,'' meaning they relate to accrual adjustments that are commonly accepted in practice — such as recording depreciation, capitalizing fixed assets, or accruing income taxes. The concept does not relate to audit opinions, entity revenue levels, or regulatory approval. It ensures modifications are well-established rather than arbitrary.', 'easy', 1),

-- Q9: medium / L2 — Tax basis constructive receipt
(2, 'Special Purpose Frameworks', 'Graystone Consulting prepares tax-basis financial statements using the cash method for tax purposes. On December 28, a client mails a $75,000 check that arrives and is available for deposit on December 31, but the controller waits until January 3 to deposit it. The firm''s year-end is December 31. Under the tax basis, when is the $75,000 recognized as revenue?', '["January 3, when the check is deposited into the bank account", "December 31, when the check was received and available without restriction", "December 28, when the client mailed the check", "January, prorated between December and January based on the service period"]'::jsonb, 1, 'Under IRC Section 451 and the constructive receipt doctrine, income is recognized when it is credited, set apart, or made available to the taxpayer without substantial limitation. Even though Graystone did not deposit the check until January 3, the funds were available on December 31. ''January 3 when deposited'' is incorrect because constructive receipt does not require physical deposit — availability is the controlling factor.', 'medium', 2),

-- Q10: easy / L2 — SPF disclosure requirements
(2, 'Special Purpose Frameworks', 'Ridgecrest Manufacturing prepares financial statements on the modified cash basis. The engagement partner reviews the notes and asks what disclosures are required. Which of the following must SPF financial statements disclose?', '["Only the accounting policies that differ from GAAP, with no other disclosures required", "Complete GAAP-level disclosures for all line items in the financial statements", "A description of the special purpose framework used and how it differs from GAAP", "A reconciliation from the SPF basis to GAAP for every material account balance"]'::jsonb, 2, 'Professional standards require SPF financial statements to include a description of the framework used and how it differs from GAAP. Additional informative disclosures similar to GAAP are required when items are the same as or similar to GAAP items. Full GAAP-level disclosures and SPF-to-GAAP reconciliations are not required — professional judgment determines which disclosures are necessary to avoid misleading users.', 'easy', 2),

-- Q11: hard / L3 — Modified cash basis mixed modifications evaluation
(2, 'Special Purpose Frameworks', 'Bridgeport Dental Associates prepares modified cash-basis financial statements. The practice currently records depreciation on equipment and capitalizes long-term debt. The office manager proposes three additional modifications: (1) accruing three-year malpractice insurance premiums paid annually, (2) recognizing a deferred tax liability for timing differences, and (3) accruing patient receivables for services billed but not yet collected. Apply the substantial support requirement to each proposed modification and determine which are acceptable.', '["All three are acceptable because they reflect economic reality more accurately than pure cash basis", "Only (1) and (3) are acceptable because they directly relate to operating activities", "Only (3) is acceptable because patient receivables represent the primary revenue stream", "Only (2) is acceptable because income tax accruals have substantial support as a long-term modification"]'::jsonb, 3, 'Under modified cash-basis standards, modifications must have substantial support — they must relate to commonly accepted long-term accrual adjustments. Income tax accruals (2) qualify because they address long-term timing effects. Prepaid insurance (1) and accounts receivable (3) are routine operating items whose accrual would push the statements too close to GAAP. The rule distinguishes long-term items (depreciation, debt, income taxes) from routine operating accruals.', 'hard', 3),

-- Q12: medium / L3 — Tax basis UNICAP Section 263A inventory impact
(2, 'Special Purpose Frameworks', 'Whitfield Industries prepares tax-basis financial statements and manufactures custom industrial components. Under GAAP, the company uses absorption costing with fixed and variable overhead. The controller asks how tax-basis inventory costing differs. Under the tax basis, how does the UNICAP requirement under IRC Section 263A affect inventory measurement?', '["Certain indirect costs that may be excluded under GAAP absorption costing must be capitalized into inventory under Section 263A", "UNICAP eliminates the need to capitalize any overhead costs into inventory", "UNICAP requires the same absorption costing method as GAAP with no additional capitalization", "UNICAP applies only to retailers and does not affect manufacturers like Whitfield"]'::jsonb, 0, 'IRC Section 263A (UNICAP) requires producers and certain resellers to capitalize specified indirect costs — including costs that might be excluded under GAAP absorption costing — into inventory. This creates a tax-GAAP difference because UNICAP''s capitalization rules can require inclusion of additional overhead costs beyond what GAAP mandates. UNICAP does not eliminate overhead capitalization, nor is it limited to retailers — it applies to manufacturers exceeding the gross receipts threshold.', 'medium', 3),

-- Q13: hard / L4 — General-use vs special-use regulatory audit report comparison
(2, 'Special Purpose Frameworks', 'Parkview Mutual Insurance prepares statutory accounting principles (SAP) financial statements for the state insurance department. The SAP basis differs materially from GAAP. Simultaneously, Valley Federal Credit Union prepares regulatory basis call reports under FFIEC requirements that are substantially equivalent to GAAP and distributed to members. Both entities engage auditors under AU-C Section 800. Evaluate the audit reporting requirements for each engagement and identify the key distinction.', '["Both auditors issue standard unmodified opinions without additional paragraphs because regulatory compliance replaces GAAP as the applicable framework", "Both auditors include emphasis-of-matter paragraphs, but only the insurance auditor adds a scope limitation paragraph citing material GAAP departures", "Both auditors include emphasis-of-matter paragraphs describing the SPF, but the insurance auditor must also include an other-matter paragraph restricting distribution because SAP is special-use while the credit union''s basis qualifies as general-use", "The insurance auditor issues a qualified opinion for GAAP departures while the credit union auditor issues an unmodified opinion since FFIEC rules approximate GAAP"]'::jsonb, 2, 'Under AU-C Section 800, all SPF audits require an emphasis-of-matter paragraph describing the framework. The critical distinction is general-use vs. special-use: when the regulatory basis is substantially equivalent to GAAP (credit union FFIEC), statements are general-use and no use restriction is needed. When the basis differs materially from GAAP (insurance SAP), statements are special-use and require an other-matter paragraph restricting distribution. Neither engagement requires a qualified opinion.', 'hard', 4),

-- Q14: hard / L4 — Tax basis multi-element conversion (DTA, leases, CECL, goodwill)
(2, 'Special Purpose Frameworks', 'Thornberry Corporation converted from GAAP to tax-basis financial statements. The CFO identifies four accounts that will change: (1) ROU assets and lease liabilities under ASC 842 will be removed, (2) the CECL allowance under ASC 326 will be eliminated, (3) deferred tax assets and liabilities will no longer be recognized, and (4) goodwill impairment testing will be replaced with Section 197 amortization. Evaluate which combination correctly reflects all four changes under the tax basis.', '["Only (1) and (4) change — tax basis still requires lease liabilities and CECL allowances", "Only (2) and (3) change — tax basis still requires operating lease liabilities and goodwill impairment", "Items (1), (2), and (3) change, but goodwill is still tested for impairment under the tax basis", "All four items change — tax basis eliminates ROU assets and lease liabilities, uses direct write-off instead of CECL, does not recognize DTAs or DTLs, and amortizes goodwill over 15 years"]'::jsonb, 3, 'The tax basis differs from GAAP on all four points: (1) tax basis generally does not recognize ROU assets or lease liabilities per ASC 842; (2) bad debts use direct write-off under IRC Section 166 rather than the CECL allowance; (3) deferred tax assets and liabilities are unnecessary because the financial statements already reflect tax rules; (4) goodwill is amortized over 15 years under IRC Section 197 rather than tested for impairment under ASC 350.', 'hard', 4),

-- Q15: medium / L2 — Other-matter paragraph restricting distribution
(2, 'Special Purpose Frameworks', 'Lakeview Ventures engages an auditor to report on financial statements prepared under a contractual basis specified in a joint venture agreement. The statements will be used only by the joint venture partners and their legal counsel. Under AU-C Section 800, what must the auditor''s report include regarding distribution?', '["A disclaimer of opinion because contractual basis statements cannot be audited", "An other-matter paragraph restricting the report''s use to the specified parties", "A standard unmodified opinion with no additional paragraphs about distribution", "A qualified opinion citing the departure from GAAP as a basis for restricted use"]'::jsonb, 1, 'Under AU-C Section 800, contractual basis financial statements are almost always special-use because they are prepared for specific parties to the agreement. The auditor''s report must include an other-matter paragraph restricting distribution to the specified users. A disclaimer is not required — the statements can be audited and an opinion issued. The restriction concerns intended users, not a GAAP departure warranting qualification.', 'medium', 2),

-- Q16: easy / L1 — Cash basis no accruals, deferrals, or estimates
(2, 'Special Purpose Frameworks', 'Which of the following is a defining characteristic of the pure cash basis of accounting?', '["Revenue is recognized when earned regardless of cash collection", "Estimates for uncollectible accounts are recorded at year-end", "No accruals, deferrals, or estimates are recorded", "Depreciation is recorded on all capital assets"]'::jsonb, 2, 'Under the pure cash basis, financial transactions are recorded only when cash is received or disbursed. No accruals (receivables, payables), deferrals (prepaid expenses, unearned revenue), or estimates (allowance for bad debts, depreciation) are recorded. This makes it the simplest framework but the least informative. Revenue recognition when earned and depreciation are accrual concepts not used under the pure cash basis.', 'easy', 1),

-- Q17: medium / L3 — Tax basis no deferred tax recognition
(2, 'Special Purpose Frameworks', 'Garrison Manufacturing prepares tax-basis financial statements. The company has $250,000 in temporary differences between GAAP book depreciation and tax depreciation that would create a deferred tax liability under ASC 740. The controller asks whether to record the deferred tax liability on the tax-basis balance sheet. Apply the tax-basis framework rules to this situation.', '["No deferred tax liability is recognized because the financial statements already reflect tax rules, eliminating the concept of temporary differences", "A deferred tax liability of $250,000 multiplied by the tax rate must be recorded because it represents a real future obligation", "A deferred tax liability is recorded but only if it exceeds 10% of total tax-basis assets", "The deferred tax liability is recorded at a discounted present value rather than the nominal amount"]'::jsonb, 0, 'Under the tax basis, financial statements already use IRC recognition and measurement rules. Since both the financial statements and the tax return follow the same rules, there are no temporary differences between book and tax amounts — the concept of deferred tax assets and liabilities from ASC 740 does not apply. When both use the same tax rules, there is nothing to defer.', 'medium', 3),

-- Q18: hard / L4 — SPF going concern + subsequent events + related party disclosures
(2, 'Special Purpose Frameworks', 'Clearwater Trading prepares cash-basis financial statements for Year 1. After year-end but before the statements are issued, the company''s largest customer representing 40% of cash receipts files for bankruptcy. Clearwater also has significant loans from its majority shareholder totaling $500,000. The CPA preparing the statements evaluates what disclosures are needed. Analyze which GAAP-like disclosures are required in these SPF financial statements.', '["No additional disclosures are required because cash-basis statements are exempt from going concern, subsequent event, and related party requirements", "Only the subsequent event requires disclosure because it affects future cash receipts; related party loans need not be disclosed under cash basis", "All three require disclosure — the subsequent event, the potential going concern implication, and the related party transactions — because SPF statements must include informative disclosures for items similar to GAAP", "Only the related party loan requires disclosure; subsequent events and going concern assessments do not apply to SPF engagements"]'::jsonb, 2, 'Professional standards require SPF financial statements to include informative disclosures similar to GAAP when the statements contain items the same as or similar to GAAP items. Going concern (AU-C 570), subsequent events (AU-C 560), and related party transactions all apply regardless of framework. The customer bankruptcy is a subsequent event affecting future operations; the shareholder loans require related party disclosure. Omitting these material items would make the cash-basis statements misleading.', 'hard', 4),

-- Q19: medium / L2 — Cash basis manipulation through payment timing
(2, 'Special Purpose Frameworks', 'Brookfield Contracting prepares cash-basis financial statements. At year-end, the controller delays $200,000 in vendor payments due December 31 until January 5 of the following year. The company also accelerates collection of $150,000 in receivables by offering clients a 2% discount for December payment. How do these actions affect Brookfield''s cash-basis income for the current year?', '["Cash-basis income is unaffected because vendor payments and collections offset each other", "Cash-basis income decreases by $50,000 due to the net timing of the two transactions", "Cash-basis income increases by $200,000 from delayed payments but decreases by $150,000 from accelerated collections", "Cash-basis income increases by $350,000 — $200,000 from delayed payments and $150,000 from accelerated collections"]'::jsonb, 3, 'Under the cash basis, expenses are recognized only when cash is paid and revenue only when cash is received. Delaying $200,000 in vendor payments to January removes those expenses from the current year (increasing income by $200,000). Accelerating $150,000 in collections into December adds that revenue to the current year (increasing income by $150,000). This $350,000 combined effect illustrates a key limitation of cash-basis reporting — income can be manipulated through payment and collection timing.', 'medium', 2),

-- Q20: hard / L4 — Modified cash basis capitalization + depreciation rationale
(2, 'Special Purpose Frameworks', 'Pinecrest Landscaping prepares modified cash-basis financial statements. The firm capitalizes equipment purchases as fixed assets and records straight-line depreciation. A new staff accountant argues that capitalizing equipment contradicts the cash basis because the cash was disbursed at purchase and should be immediately expensed. The engagement partner disagrees. Evaluate whether the capitalization modification is proper and explain why.', '["The staff accountant is correct — capitalizing equipment is inconsistent with the cash basis because the cash outflow occurred at purchase and must be expensed immediately", "The engagement partner is correct — capitalizing fixed assets and recording depreciation are modifications with substantial support because they address the long-term nature of the asset", "Both are partially correct — equipment should be expensed at purchase, but a supplemental depreciation schedule should be disclosed in the notes", "Neither is correct — under the modified cash basis, equipment must be recorded at fair value with annual revaluation rather than historical cost with depreciation"]'::jsonb, 1, 'Under modified cash-basis standards, capitalizing fixed assets and recording depreciation are modifications that have substantial support. Long-lived assets provide benefits over multiple periods, and recognizing this through capitalization and systematic depreciation is a commonly accepted accrual adjustment. The principle is that modifications for items with long-term effects (depreciation, debt, income taxes) are acceptable, while modifications for routine operating items would push the framework too close to GAAP.', 'hard', 4),

-- Q21: medium / L3 — SSARS compilation report SPF requirements
(2, 'Special Purpose Frameworks', 'Mason & Clark CPAs is performing a compilation of financial statements prepared on the modified cash basis for Elmwood Bakery. The compilation report draft identifies the statements as prepared under "a basis other than GAAP" but does not specify the framework or reference any notes. The engagement partner reviews the draft and identifies the deficiency. Under SSARS, what must the compilation report include?', '["Identification of the specific special purpose framework used and a reference to the note describing the framework", "A general statement that the framework is a basis other than GAAP, which is sufficient without further detail", "A reconciliation from the modified cash basis to GAAP to explain all material differences", "A statement that the CPA takes no responsibility for the framework choice made by management"]'::jsonb, 0, 'Under SSARS (AR-C Section 80), a compilation report for SPF financial statements must specifically identify the applicable special purpose framework (e.g., modified cash basis) and include a reference to the note that describes the basis. Simply stating ''a basis other than GAAP'' without identifying the specific framework or referencing the explanatory note is insufficient and fails to meet the reporting standards.', 'medium', 3),

-- Q22: medium / L3 — S corporation tax basis flow-through reporting
(2, 'Special Purpose Frameworks', 'Riverdale Properties is an S corporation that prepares tax-basis financial statements. The company reports $650,000 in tax-basis net income and $85,000 in shareholder distributions during the year. The controller is determining how to present the equity section. Under the tax-basis framework for an S corporation, how should net income and distributions be reported?', '["Net income of $650,000 flows to retained earnings, and distributions are netted against income on the income statement", "Only the $565,000 net of income less distributions is reported because S corporations pass through net amounts", "Net income is not reported because S corporation income passes through to individual shareholders on their personal returns", "Net income of $650,000 is reported on the tax-basis income statement, and the $85,000 in distributions reduce shareholders'' equity on the balance sheet"]'::jsonb, 3, 'Under the tax basis, an S corporation reports its full net income on the tax-basis income statement regardless of pass-through status. While the income flows through to shareholders'' individual returns (Schedule K-1), the entity-level financial statements still present the income earned. Shareholder distributions reduce equity on the balance sheet, similar to how GAAP dividends reduce retained earnings. The entity does not net income against distributions.', 'medium', 3),

-- Q23: medium / L3 — Regulatory basis FFIEC bank call reports
(2, 'Special Purpose Frameworks', 'Valley Federal Savings prepares quarterly call reports as required by the Federal Financial Institutions Examination Council (FFIEC). The call reports use specific measurement rules prescribed by the FFIEC that differ from certain GAAP requirements. The bank''s external auditor is determining which special purpose framework applies. Apply the SPF classification criteria to these financial statements.', '["Tax basis, because the call reports follow government-prescribed rules similar to IRC requirements", "Regulatory basis, because the FFIEC is a governmental regulatory agency prescribing specific financial reporting rules", "Contractual basis, because the bank is contractually required to file call reports as a condition of its charter", "Modified cash basis, because the FFIEC rules modify GAAP rather than replace it entirely"]'::jsonb, 1, 'Under AU-C Section 800, financial statements prepared in accordance with requirements prescribed by a governmental regulatory agency qualify as regulatory basis. The FFIEC is a governmental body that prescribes specific measurement and recognition rules for banks and credit unions. This is distinct from contractual basis (arising from private agreements) and tax basis (following IRC rules). The charter filing requirement does not transform the regulatory basis into a contractual basis.', 'medium', 3),

-- Q24: easy / L1 — SPF reduces complexity and cost
(2, 'Special Purpose Frameworks', 'What is the primary reason small and mid-sized entities use special purpose frameworks instead of GAAP?', '["To reduce the complexity and cost of financial reporting", "To avoid the requirement to engage a CPA for financial statement preparation", "To eliminate the need for any financial disclosures in the notes", "To qualify for preferential tax treatment from the IRS"]'::jsonb, 0, 'Special purpose frameworks exist primarily to reduce reporting complexity and cost for entities that do not need full GAAP compliance. Small and mid-sized entities benefit from simpler recognition and measurement rules while still producing meaningful financial information. SPFs do not eliminate the need for CPAs, do not remove all disclosure requirements, and do not provide tax advantages — they offer a less complex reporting alternative.', 'easy', 1),

-- Q25: easy / L1 — Tax basis IRC Section 197 intangibles
(2, 'Special Purpose Frameworks', 'Under the tax basis of accounting, how are Section 197 intangible assets such as trademarks and customer lists reported?', '["Expensed immediately upon acquisition", "Tested for impairment annually but never amortized", "Amortized on a straight-line basis over 15 years", "Reported at fair value with changes recognized in income"]'::jsonb, 2, 'Under IRC Section 197, acquired intangible assets — including goodwill, trademarks, customer lists, and covenants not to compete — are amortized on a straight-line basis over 15 years. This contrasts with GAAP, where goodwill is not amortized but tested for impairment under ASC 350, and other intangibles may have varying useful lives. The mandatory 15-year period applies regardless of the intangible''s actual economic life.', 'easy', 1),

-- Q26: medium / L2 — SPF related party disclosures still required
(2, 'Special Purpose Frameworks', 'Summerfield Properties prepares tax-basis financial statements. The company leases its office building from a partnership owned by the company''s CEO at $15,000 per month. The controller believes related party disclosures are unnecessary because the entity does not follow GAAP. Under professional standards for SPF financial statements, is the controller correct?', '["Yes, related party disclosures apply only to GAAP financial statements and are not required for SPFs", "No, SPF financial statements must include informative disclosures similar to GAAP for items such as related party transactions when omission would be misleading", "Yes, but only if the related party transaction exceeds a materiality threshold of 5% of total assets", "No, but the disclosure is limited to stating that related parties exist without quantifying the transactions"]'::jsonb, 1, 'Professional standards require SPF financial statements to include informative disclosures similar to GAAP when statements contain items the same as or similar to GAAP items. Related party transactions (addressed under ASC 850 for GAAP) must be disclosed if their omission would make the statements misleading. The $15,000 monthly lease with the CEO''s partnership is a material related party transaction requiring disclosure of the nature, terms, and amounts.', 'medium', 2),

-- Q27: easy / L1 — Cash basis no receivables or payables
(2, 'Special Purpose Frameworks', 'Which accounts are absent from a balance sheet prepared under the pure cash basis of accounting?', '["Cash and equity accounts", "Only inventory and prepaid expenses", "Only long-term debt and deferred revenue", "Accounts receivable, accounts payable, and accrued liabilities"]'::jsonb, 3, 'Under the pure cash basis, only cash transactions are recorded. Accounts receivable (amounts owed by customers), accounts payable (amounts owed to vendors), and accrued liabilities (expenses incurred but not yet paid) do not exist because they represent non-cash accrual concepts. Cash and equity accounts remain on the cash-basis balance sheet. Inventory and prepaid expenses are also absent, but the most comprehensive answer includes receivables, payables, and accrued liabilities.', 'easy', 1),

-- Q28: medium / L2 — Contractual basis special-use restriction
(2, 'Special Purpose Frameworks', 'Harborview Development Group prepares financial statements under the financial reporting provisions in its construction loan agreement with Pacific Regional Bank. The CFO wants to distribute these statements to potential equity investors who are not parties to the loan. Under AU-C Section 800, what restriction applies to contractual basis financial statements?', '["They are almost always classified as special-use and should be restricted to the parties specified in the contract", "They may be freely distributed if the auditor issues an unmodified opinion on the statements", "They become general-use once the financial statements receive an unqualified audit opinion", "They may be distributed to any party as long as a disclaimer of GAAP compliance is attached"]'::jsonb, 0, 'Under AU-C Section 800, contractual basis financial statements are almost always special-use because they are prepared specifically for the parties to the agreement. The auditor''s report includes an other-matter paragraph restricting distribution to specified parties. Distributing these statements to equity investors not party to the loan would be inappropriate because the reporting provisions are tailored to the contract''s specific terms, not for general-purpose use.', 'medium', 2),

-- Q29: medium / L3 — Auditor unmodified opinion on SPF (not qualified for GAAP departure)
(2, 'Special Purpose Frameworks', 'Palmer & Associates audits financial statements prepared on the income tax basis for Cartwell Distributors. The auditor confirms the statements are fairly presented in accordance with the tax basis and all required disclosures are included. A junior auditor suggests the report should contain a qualified opinion because the statements depart from GAAP. Apply AU-C Section 800 to determine the correct opinion.', '["Qualified opinion, because any departure from GAAP requires qualification regardless of the framework used", "Adverse opinion, because tax-basis statements are materially different from GAAP in all cases", "Unmodified opinion, because the auditor opines on fair presentation under the applicable SPF rather than on GAAP compliance", "Disclaimer of opinion, because the auditor cannot express certainty about a non-GAAP framework"]'::jsonb, 2, 'Under AU-C Section 800, when financial statements are prepared under a recognized special purpose framework, the auditor expresses an opinion on whether the statements are fairly presented in accordance with that framework — not GAAP. If the statements fairly present under the tax basis, an unmodified opinion is appropriate. Using an SPF is not a GAAP departure requiring qualification; it is a recognized alternative framework with its own fair presentation standard.', 'medium', 3),

-- Q30: medium / L2 — Tax basis prepaid expenses under cash method
(2, 'Special Purpose Frameworks', 'Westbrook Consulting prepares tax-basis financial statements using the cash method. The company pays $36,000 on November 1 for a 12-month professional liability insurance policy covering November through the following October. Under the tax basis with the cash method, how is the $36,000 insurance payment reported?', '["$6,000 is expensed in the current year and $30,000 is recorded as a prepaid asset", "$36,000 is expensed in the current year when paid because the cash method recognizes expenses upon disbursement", "$3,000 per month is expensed over the 12-month policy period on a straight-line basis", "$36,000 is recorded as a prepaid asset and amortized ratably over the next 12 months"]'::jsonb, 1, 'Under the tax basis with the cash method, expenses are recognized when cash is disbursed. The full $36,000 insurance payment is expensed in the year paid, regardless of the coverage period extending into the next year. Under GAAP, the payment would be allocated as a prepaid asset and expensed monthly. Note: under Reg. 1.263(a)-4, the IRS 12-month rule permits full deduction of prepaid expenses not extending beyond 12 months after the benefit begins.', 'medium', 2)
;

COMMIT;
